-- Cover illustrations for courses and modules, generated by Gemini and
-- stored in a public bucket. Module covers live in courses.modules (jsonb,
-- a "cover" URL per module); the course's own cover gets a column.

alter table public.courses add column if not exists cover_url text;

insert into storage.buckets (id, name, public)
values ('covers', 'covers', true)
on conflict (id) do nothing;

-- The server uploads with the publishable key (the anon role): it may add
-- images to this bucket only, and anyone may read them.
drop policy if exists "covers read" on storage.objects;
create policy "covers read" on storage.objects
  for select to anon using (bucket_id = 'covers');

drop policy if exists "covers upload" on storage.objects;
create policy "covers upload" on storage.objects
  for insert to anon with check (bucket_id = 'covers');
